-- sumber & penjelasan soal: bab, pdf, halaman, kalimat ber-furigana, kosakata
alter table soal add column if not exists bab text;
alter table soal add column if not exists sumber_pdf text;
alter table soal add column if not exists halaman int;
alter table soal add column if not exists kalimat text;
alter table soal add column if not exists kalimat_ruby text;
alter table soal add column if not exists kosakata jsonb;

update soal set bab='00 はじめに・旅館業法', sumber_pdf='2号', halaman=6, kalimat='宿泊施設は、宿泊者の氏名、住所、職業、宿泊日数などを記録した宿泊者名簿を作成し、一定期間保管する義務があります。', kalimat_ruby='<ruby>宿泊施設<rt>しゅくはくしせつ</rt></ruby>は、<ruby>宿泊者<rt>しゅくはくしゃ</rt></ruby>の<ruby>氏名<rt>しめい</rt></ruby>、<ruby>住所<rt>じゅうしょ</rt></ruby>、職業、<ruby>宿泊<rt>しゅくはく</rt></ruby>日数などを<ruby>記録<rt>きろく</rt></ruby>した<ruby>宿泊者<rt>しゅくはくしゃ</rt></ruby><ruby>名簿<rt>めいぼ</rt></ruby>を<ruby>作成<rt>さくせい</rt></ruby>し、<ruby>一定期間<rt>いっていきかん</rt></ruby><ruby>保管<rt>ほかん</rt></ruby>する<ruby>義務<rt>ぎむ</rt></ruby>があります。', kosakata='[{"k": "宿泊施設", "y": "しゅくはくしせつ", "a": "fasilitas penginapan"}, {"k": "一定期間", "y": "いっていきかん", "a": "jangka waktu tertentu"}, {"k": "宿泊者", "y": "しゅくはくしゃ", "a": "tamu yang menginap"}, {"k": "氏名", "y": "しめい", "a": "nama lengkap"}, {"k": "保管", "y": "ほかん", "a": "penyimpanan"}, {"k": "作成", "y": "さくせい", "a": "membuat (dokumen)"}, {"k": "名簿", "y": "めいぼ", "a": "daftar nama"}, {"k": "住所", "y": "じゅうしょ", "a": "alamat"}]'::jsonb where kategori = '宿泊分野' and urutan=1;
update soal set bab='01 フロント業務', sumber_pdf='2号', halaman=16, kalimat='外国人のお客様が日本の宿泊施設に泊まる場合は、パスポートのコピーをとって定められた期間保管する必要があります。', kalimat_ruby='<ruby>外国人<rt>がいこくじん</rt></ruby>の<ruby>お客様<rt>おきゃくさま</rt></ruby>が<ruby>日本<rt>にほん</rt></ruby>の<ruby>宿泊施設<rt>しゅくはくしせつ</rt></ruby>に泊まる<ruby>場合<rt>ばあい</rt></ruby>は、パスポートのコピーをとって<ruby>定め<rt>さだめ</rt></ruby>られた<ruby>期間<rt>きかん</rt></ruby><ruby>保管<rt>ほかん</rt></ruby>する<ruby>必要<rt>ひつよう</rt></ruby>があります。', kosakata='[{"k": "宿泊施設", "y": "しゅくはくしせつ", "a": "fasilitas penginapan"}, {"k": "コピー", "y": "", "a": "salinan"}, {"k": "お客様", "y": "おきゃくさま", "a": "tamu / pelanggan"}, {"k": "外国人", "y": "がいこくじん", "a": "warga asing"}, {"k": "場合", "y": "ばあい", "a": "kasus / kalau"}, {"k": "必要", "y": "ひつよう", "a": "perlu / diperlukan"}, {"k": "日本", "y": "にほん", "a": "Jepang"}, {"k": "定め", "y": "さだめ", "a": "ketentuan"}]'::jsonb where kategori = '宿泊分野' and urutan=2;
update soal set bab='01 フロント業務', sumber_pdf='2号', halaman=15, kalimat='チェックインの際には、お客様に予約の有無と予約内容を確認する必要があります。', kalimat_ruby='チェックインの<ruby>際に<rt>さいに</rt></ruby>は、<ruby>お客様<rt>おきゃくさま</rt></ruby>に<ruby>予約<rt>よやく</rt></ruby>の<ruby>有無<rt>うむ</rt></ruby>と<ruby>予約<rt>よやく</rt></ruby><ruby>内容<rt>ないよう</rt></ruby>を<ruby>確認<rt>かくにん</rt></ruby>する<ruby>必要<rt>ひつよう</rt></ruby>があります。', kosakata='[{"k": "チェック", "y": "", "a": "pengecekan"}, {"k": "お客様", "y": "おきゃくさま", "a": "tamu / pelanggan"}, {"k": "予約", "y": "よやく", "a": "reservasi"}, {"k": "確認", "y": "かくにん", "a": "konfirmasi / pengecekan"}, {"k": "必要", "y": "ひつよう", "a": "perlu / diperlukan"}, {"k": "内容", "y": "ないよう", "a": "isi"}, {"k": "有無", "y": "うむ", "a": "ada atau tidaknya"}, {"k": "際に", "y": "さいに", "a": "ketika / pada saat"}]'::jsonb where kategori = '宿泊分野' and urutan=3;
update soal set bab='01 フロント業務', sumber_pdf='2号', halaman=20, kalimat='必ずドアをノックするか呼び鈴を鳴らし、お客様が「入ってください」という許可をもらってから客室に入らなければいけません。', kalimat_ruby='<ruby>必ず<rt>かならず</rt></ruby>ドアをノックするか呼び鈴を鳴らし、<ruby>お客様<rt>おきゃくさま</rt></ruby>が「入ってください」という<ruby>許可<rt>きょか</rt></ruby>をもらってから<ruby>客室<rt>きゃくしつ</rt></ruby>に入らなければいけません。', kosakata='[{"k": "お客様", "y": "おきゃくさま", "a": "tamu / pelanggan"}, {"k": "客室", "y": "きゃくしつ", "a": "kamar tamu"}, {"k": "必ず", "y": "かならず", "a": "wajib / pasti"}, {"k": "許可", "y": "きょか", "a": "izin"}, {"k": "ドア", "y": "", "a": "pintu"}]'::jsonb where kategori = '宿泊分野' and urutan=4;
update soal set bab='01 フロント業務', sumber_pdf='2号', halaman=20, kalimat='お客様本人以外の方から部屋番号をたずねられた際は、滞在中のお客様に確認して、了解を得てからお伝えします。', kalimat_ruby='<ruby>お客様<rt>おきゃくさま</rt></ruby>本人<ruby>以外<rt>いがい</rt></ruby>の方から<ruby>部屋<rt>へや</rt></ruby><ruby>番号<rt>ばんごう</rt></ruby>をたずねられた際は、<ruby>滞在中<rt>たいざいちゅう</rt></ruby>の<ruby>お客様<rt>おきゃくさま</rt></ruby>に<ruby>確認<rt>かくにん</rt></ruby>して、了解を得てからお<ruby>伝え<rt>つたえ</rt></ruby>します。', kosakata='[{"k": "お客様", "y": "おきゃくさま", "a": "tamu / pelanggan"}, {"k": "滞在中", "y": "たいざいちゅう", "a": "selama menginap"}, {"k": "確認", "y": "かくにん", "a": "konfirmasi / pengecekan"}, {"k": "部屋", "y": "へや", "a": "kamar"}, {"k": "以外", "y": "いがい", "a": "selain"}, {"k": "伝え", "y": "つたえ", "a": "menyampaikan"}, {"k": "番号", "y": "ばんごう", "a": "nomor"}]'::jsonb where kategori = '宿泊分野' and urutan=5;
update soal set bab='01 フロント業務', sumber_pdf='2号', halaman=19, kalimat='お客様との電話を切る際には、必ず、お客様が電話を切ってから電話を切るようにします。', kalimat_ruby='<ruby>お客様<rt>おきゃくさま</rt></ruby>との<ruby>電話を切る<rt>でんわをきる</rt></ruby><ruby>際に<rt>さいに</rt></ruby>は、<ruby>必ず<rt>かならず</rt></ruby>、<ruby>お客様<rt>おきゃくさま</rt></ruby>が<ruby>電話<rt>でんわ</rt></ruby>を切ってから<ruby>電話を切る<rt>でんわをきる</rt></ruby>ようにします。', kosakata='[{"k": "電話を切る", "y": "でんわをきる", "a": "menutup telepon"}, {"k": "お客様", "y": "おきゃくさま", "a": "tamu / pelanggan"}, {"k": "必ず", "y": "かならず", "a": "wajib / pasti"}, {"k": "際に", "y": "さいに", "a": "ketika / pada saat"}]'::jsonb where kategori = '宿泊分野' and urutan=6;
update soal set bab='01 フロント業務', sumber_pdf='2号', halaman=22, kalimat='持ち主が見つからない場合は、一定期間保管した後に、警察に遺失物として届けます。', kalimat_ruby='<ruby>持ち主<rt>もちぬし</rt></ruby>が見つからない<ruby>場合<rt>ばあい</rt></ruby>は、<ruby>一定期間<rt>いっていきかん</rt></ruby><ruby>保管<rt>ほかん</rt></ruby>した<ruby>後に<rt>のちに</rt></ruby>、<ruby>警察<rt>けいさつ</rt></ruby>に<ruby>遺失物<rt>いしつぶつ</rt></ruby>として<ruby>届け<rt>とどけ</rt></ruby>ます。', kosakata='[{"k": "一定期間", "y": "いっていきかん", "a": "jangka waktu tertentu"}, {"k": "持ち主", "y": "もちぬし", "a": "pemilik"}, {"k": "遺失物", "y": "いしつぶつ", "a": "barang hilang"}, {"k": "場合", "y": "ばあい", "a": "kasus / kalau"}, {"k": "保管", "y": "ほかん", "a": "penyimpanan"}, {"k": "届け", "y": "とどけ", "a": "laporan / pengantaran"}, {"k": "後に", "y": "のちに", "a": "setelah itu"}, {"k": "警察", "y": "けいさつ", "a": "polisi"}]'::jsonb where kategori = '宿泊分野' and urutan=7;
update soal set bab='03 接客', sumber_pdf='2号', halaman=38, kalimat='会釈は、お客様とすれ違う時やテーブルにうかがった時などに使う、約15°前傾のおじぎです。', kalimat_ruby='<ruby>会釈<rt>えしゃく</rt></ruby>は、<ruby>お客様<rt>おきゃくさま</rt></ruby>と<ruby>すれ違う<rt>すれちがう</rt></ruby>時やテーブルにうかがった時などに使う、約15°<ruby>前傾<rt>ぜんけい</rt></ruby>のおじぎです。', kosakata='[{"k": "テーブル", "y": "", "a": "meja"}, {"k": "すれ違う", "y": "すれちがう", "a": "berpapasan"}, {"k": "お客様", "y": "おきゃくさま", "a": "tamu / pelanggan"}, {"k": "前傾", "y": "ぜんけい", "a": "condong ke depan"}, {"k": "会釈", "y": "えしゃく", "a": "bungkuk ringan ±15°"}]'::jsonb where kategori = '宿泊分野' and urutan=8;
update soal set bab='03 接客', sumber_pdf='2号', halaman=38, kalimat='普通礼（敬礼）は、お客様をお迎えする時をはじめとして、様々な場面で最も使う、約30°前傾のおじぎです。', kalimat_ruby='普通礼（<ruby>敬礼<rt>けいれい</rt></ruby>）は、<ruby>お客様<rt>おきゃくさま</rt></ruby>をお迎えする時をはじめとして、<ruby>様々<rt>さまざま</rt></ruby>な場面で<ruby>最も<rt>もっとも</rt></ruby>使う、約30°<ruby>前傾<rt>ぜんけい</rt></ruby>のおじぎです。', kosakata='[{"k": "お客様", "y": "おきゃくさま", "a": "tamu / pelanggan"}, {"k": "前傾", "y": "ぜんけい", "a": "condong ke depan"}, {"k": "最も", "y": "もっとも", "a": "paling"}, {"k": "敬礼", "y": "けいれい", "a": "ojigi ±30°"}, {"k": "様々", "y": "さまざま", "a": "berbagai"}]'::jsonb where kategori = '宿泊分野' and urutan=9;
update soal set bab='03 接客', sumber_pdf='2号', halaman=40, kalimat='宿泊施設内でお客様をご案内する際には、2～3歩、左前方を、お客様の歩調に合わせながら歩きます。', kalimat_ruby='<ruby>宿泊施設<rt>しゅくはくしせつ</rt></ruby>内で<ruby>お客様<rt>おきゃくさま</rt></ruby>を<ruby>ご案内<rt>ごあんない</rt></ruby>する<ruby>際に<rt>さいに</rt></ruby>は、2～3歩、左前方を、<ruby>お客様<rt>おきゃくさま</rt></ruby>の歩調に合わせながら歩きます。', kosakata='[{"k": "宿泊施設", "y": "しゅくはくしせつ", "a": "fasilitas penginapan"}, {"k": "お客様", "y": "おきゃくさま", "a": "tamu / pelanggan"}, {"k": "ご案内", "y": "ごあんない", "a": "pengarahan (hormat)"}, {"k": "際に", "y": "さいに", "a": "ketika / pada saat"}]'::jsonb where kategori = '宿泊分野' and urutan=10;
update soal set bab='01 フロント業務', sumber_pdf='2号', halaman=14, kalimat='チェックイン業務では、予約内容を確認し、ご宿泊の手続き、ルームキーのお渡し、館内・設備の説明などをします。', kalimat_ruby='チェックイン<ruby>業務<rt>ぎょうむ</rt></ruby>では、<ruby>予約<rt>よやく</rt></ruby><ruby>内容<rt>ないよう</rt></ruby>を<ruby>確認<rt>かくにん</rt></ruby>し、ご<ruby>宿泊<rt>しゅくはく</rt></ruby>の<ruby>手続き<rt>てつづき</rt></ruby>、ルームキーのお渡し、<ruby>館内<rt>かんない</rt></ruby>・<ruby>設備<rt>せつび</rt></ruby>の<ruby>説明<rt>せつめい</rt></ruby>などをします。', kosakata='[{"k": "チェック", "y": "", "a": "pengecekan"}, {"k": "ルーム", "y": "", "a": "kamar"}, {"k": "手続き", "y": "てつづき", "a": "prosedur"}, {"k": "業務", "y": "ぎょうむ", "a": "pekerjaan / tugas kerja"}, {"k": "宿泊", "y": "しゅくはく", "a": "menginap / penginapan"}, {"k": "予約", "y": "よやく", "a": "reservasi"}, {"k": "館内", "y": "かんない", "a": "di dalam gedung / area hotel"}, {"k": "確認", "y": "かくにん", "a": "konfirmasi / pengecekan"}]'::jsonb where kategori = '宿泊分野' and urutan=11;
update soal set bab='03 接客', sumber_pdf='2号', halaman=42, kalimat='宿泊施設が丁寧に心を込めて接客していたとしても、必ずクレーム（苦情）は発生します。', kalimat_ruby='<ruby>宿泊施設<rt>しゅくはくしせつ</rt></ruby>が<ruby>丁寧<rt>ていねい</rt></ruby>に心を込めて<ruby>接客<rt>せっきゃく</rt></ruby>していたとしても、<ruby>必ず<rt>かならず</rt></ruby>クレーム（<ruby>苦情<rt>くじょう</rt></ruby>）は<ruby>発生<rt>はっせい</rt></ruby>します。', kosakata='[{"k": "クレーム", "y": "", "a": "komplain"}, {"k": "宿泊施設", "y": "しゅくはくしせつ", "a": "fasilitas penginapan"}, {"k": "接客", "y": "せっきゃく", "a": "melayani tamu"}, {"k": "苦情", "y": "くじょう", "a": "keluhan / komplain"}, {"k": "必ず", "y": "かならず", "a": "wajib / pasti"}, {"k": "発生", "y": "はっせい", "a": "terjadi / timbul"}, {"k": "丁寧", "y": "ていねい", "a": "sopan / teliti"}]'::jsonb where kategori = '宿泊分野' and urutan=12;
update soal set bab='04 レストランサービス', sumber_pdf='2号', halaman=53, kalimat='食物アレルギーとは、特定のアレルギー成分を含んだ食べ物を食べた後に、アレルギー症状が引き起こされることです。', kalimat_ruby='<ruby>食物<rt>しょくもつ</rt></ruby>アレルギーとは、<ruby>特定<rt>とくてい</rt></ruby>のアレルギー成分を含んだ食べ物を食べた<ruby>後に<rt>のちに</rt></ruby>、アレルギー<ruby>症状<rt>しょうじょう</rt></ruby>が<ruby>引き<rt>ひき</rt></ruby>起こされることです。', kosakata='[{"k": "アレルギー", "y": "", "a": "alergi"}, {"k": "食物", "y": "しょくもつ", "a": "makanan"}, {"k": "特定", "y": "とくてい", "a": "tertentu / spesifik"}, {"k": "引き", "y": "ひき", "a": "menarik"}, {"k": "症状", "y": "しょうじょう", "a": "gejala"}, {"k": "後に", "y": "のちに", "a": "setelah itu"}]'::jsonb where kategori = '宿泊分野' and urutan=13;
update soal set bab='01 フロント業務', sumber_pdf='2号', halaman=22, kalimat='KPI として設定されるADR、RevPAR、OCC（客室稼働率）などをしっかりと把握しておく必要があります。', kalimat_ruby='KPI として<ruby>設定<rt>せってい</rt></ruby>されるADR、RevPAR、OCC（<ruby>客室稼働率<rt>きゃくしつかどうりつ</rt></ruby>）などをしっかりと<ruby>把握<rt>はあく</rt></ruby>しておく<ruby>必要<rt>ひつよう</rt></ruby>があります。', kosakata='[{"k": "客室稼働率", "y": "きゃくしつかどうりつ", "a": "tingkat okupansi kamar"}, {"k": "必要", "y": "ひつよう", "a": "perlu / diperlukan"}, {"k": "把握", "y": "はあく", "a": "memahami (situasi)"}, {"k": "設定", "y": "せってい", "a": "pengaturan"}]'::jsonb where kategori = '宿泊分野' and urutan=14;
update soal set bab='00 はじめに・旅館業法', sumber_pdf='2号', halaman=6, kalimat='旅館業を営むためには都道府県知事または保健所長の許可が必要です。', kalimat_ruby='<ruby>旅館業<rt>りょかんぎょう</rt></ruby>を<ruby>営む<rt>いとなむ</rt></ruby>ためには都道府県知事または<ruby>保健所<rt>ほけんじょ</rt></ruby>長の<ruby>許可<rt>きょか</rt></ruby>が<ruby>必要<rt>ひつよう</rt></ruby>です。', kosakata='[{"k": "旅館業", "y": "りょかんぎょう", "a": "usaha penginapan"}, {"k": "保健所", "y": "ほけんじょ", "a": "kantor kesehatan masyarakat (hokenjo)"}, {"k": "必要", "y": "ひつよう", "a": "perlu / diperlukan"}, {"k": "許可", "y": "きょか", "a": "izin"}, {"k": "営む", "y": "いとなむ", "a": "menjalankan (usaha)"}]'::jsonb where kategori = '宿泊分野' and urutan=15;
